mapper.select:
SELECT 
FROM promotion_auction_window
WHERE resource_type = #{resourceType}
  AND window_start_at = #{startAt}
  AND window_end_at = #{endAt}
LIMIT 1

SELECT 
FROM promotion_auction_window
WHERE status = 'SETTLED'
  AND settled_at IS NOT NULL
  AND settled_at >= #{lookbackStart}
  AND (
    #{lastSettledAt} IS NULL
    OR settled_at > #{lastSettledAt}
    OR (settled_at = #{lastSettledAt} AND id > #{lastWindowId})
  )
ORDER BY settled_at ASC, id ASC
LIMIT #{batchSize}

